81	/**
82	 * {@link AbstractOfficeSource} for Spring Boot.
83	 */
84	public class SpringBootOfficeSource extends AbstractOfficeSource {
85	
86	    private final ObjectMapper objectMapper;
87	
88	    private final List<OfficeFloorRestEndpoint> restEndpoints;
89	
90	    private final ConfigurableApplicationContext applicationContext;
91	
92	    private final Map<String, OfficeManagedObject> springArguments = new HashMap<>();
93	
94	    private final OpenAPI openApi;
95	
96	    private final List<SpringExceptionHandler> exceptionHandlers;
97	
98	    /**
99	     * @param objectMapper       {@link ObjectMapper}.
100	     * @param restEndpoints      REST endpoints.
101	     * @param applicationContext {@link ConfigurableApplicationContext}.
102	     * @param openApi            {@link OpenAPI}.
103	     * @param exceptionHandlers  {@link SpringExceptionHandler} instances.
104	     */
105	    public SpringBootOfficeSource(ObjectMapper objectMapper,
106	                                  List<OfficeFloorRestEndpoint> restEndpoints,
107	                                  ConfigurableApplicationContext applicationContext,
108	                                  OpenAPI openApi,
109	                                  List<SpringExceptionHandler> exceptionHandlers) {
110	        this.objectMapper = objectMapper;
111	        this.restEndpoints = restEndpoints;
112	        this.applicationContext = applicationContext;
113	        this.openApi = openApi;
114	        this.exceptionHandlers = exceptionHandlers;
115	    }
116	
117	    /**
118	     * Loads the {@link CorsConfiguration} from the {@link RestPathContext}.
119	     *
120	     * @param path {@link RestPathContext}.
121	     * @return {@link CorsConfiguration} or <code>null</code> if no CORS configured.
122	     */
123	    private static CorsConfiguration loadCorsConfiguration(RestPathContext path) {
124	
125	        // Drop out of recursion when at root
126	        if (path == null) {
127	            return null;
128	        }
129	
130	        // Shorter path has lower precedence
131	        CorsConfiguration parentCors = loadCorsConfiguration(path.getParentPath());
132	
133	        // Obtain the CORS from current path segment
134	        ComposeCorsConfiguration composeConfiguration = path.getConfiguration("cors", ComposeCorsConfiguration.class);
135	
136	        // Return the combined CORS, taking longer path as precedence
137	        return OfficeFloorRestEndpoint.combineCors(OfficeFloorRestEndpoint.createCorsConfiguration(composeConfiguration), parentCors);
138	    }
139	
140	    /*
141	     * ======================= OfficeSource ========================
142	     */
143	
144	    @Override
145	    protected void loadSpecification(SpecificationContext specificationContext) {
146	        // No specification
147	    }
148	
149	    @Override
150	    public void sourceOffice(OfficeArchitect officeArchitect, OfficeSourceContext officeSourceContext) throws Exception {
151	
152	        // Employ the architects
153	        WebArchitect webArchitect = WebArchitectEmployer.employWebArchitect(officeArchitect, officeSourceContext);
154	        ComposeArchitect composeArchitect = ComposeEmployer.employComposeArchitect(officeArchitect, officeSourceContext);
155	        RestArchitect restArchitect = RestEmployer.employRestArchitect(officeArchitect, webArchitect, composeArchitect, officeSourceContext);
156	
157	        // Enable auto-wiring of teams to managed functions, but only when teams are configured
158	        TeamEmployer.enableOfficeAutoWireTeams("officefloor/teams", officeArchitect);
159	
160	        // Build the shared property list used for all YAML-based classpath loading
161	        PropertyList propertyList = officeSourceContext.createPropertyList();
162	        for (String propertyName : officeSourceContext.getPropertyNames()) {
163	            propertyList.addProperty(propertyName).setValue(officeSourceContext.getProperty(propertyName));
164	        }
165	
166	        // Load managed objects from officefloor/managedobjects/
167	        ManagedObjectEmployer.employManagedObjectArchitect(officeArchitect, composeArchitect, officeSourceContext)
168	                .addManagedObjects("officefloor/managedobjects", propertyList);
169	
170	        // Load suppliers from officefloor/suppliers/
171	        SupplierEmployer.employSupplierArchitect(officeArchitect, officeSourceContext)
172	                .addSuppliers("officefloor/suppliers", propertyList);
173	
174	        // Load governance from officefloor/govern/ and register each by name in ComposeArchitect
175	        // so REST YAML files can reference them via govern: [ name ]
176	        GovernanceEmployer.employGovernanceArchitect(officeArchitect, composeArchitect, officeSourceContext)
177	                .addGovernances("officefloor/govern", propertyList)
178	                .forEach(composeArchitect::addGovernance);
179	
180	        // Load global exception handlers from officefloor/escalation/
181	        EscalationEmployer.employEscalationArchitect(officeArchitect, composeArchitect, officeSourceContext)
182	                .addEscalations("officefloor/escalation", propertyList);
183	
184	        // Undertake Spring Boot extensions
185	        for (OfficeFloorSpringBootExtension springBootExtension : officeSourceContext.loadOptionalServices(OfficeFloorSpringBootExtensionServiceFactory.class)) {
186	            springBootExtension.extendSpringBootSupport(new OfficeFloorSpringBootExtensionContext() {
187	                @Override
188	                public OfficeArchitect getOfficeArchitect() {
189	                    return officeArchitect;
190	                }
191	
192	                @Override
193	                public OfficeSourceContext getOfficeSourceContext() {
194	                    return officeSourceContext;
195	                }
196	
197	                @Override
198	                public ComposeArchitect getComposeArchitect() {
199	                    return composeArchitect;
200	                }
201	
202	                @Override
203	                public RestArchitect getRestArchitect() {
204	                    return restArchitect;
205	                }
206	
207	                @Override
208	                public ConfigurableApplicationContext getApplicationContext() {
209	                    return SpringBootOfficeSource.this.applicationContext;
210	                }
211	            });
212	        }
213	
214	        // Configure object requests
215	        webArchitect.addHttpObjectParser(new JacksonHttpObjectParserFactory(this.objectMapper));
216	
217	        // Load the Spring Exception Handlers
218	        for (SpringExceptionHandler springExceptionHandler : officeSourceContext.loadOptionalServices(SpringExceptionHandlerServiceFactory.class)) {
219	            if (springExceptionHandler != null) {
220	                this.exceptionHandlers.add(springExceptionHandler);
221	            }
222	        }
223	
224	        // Allow Spring to handle responses
225	        webArchitect.addHttpObjectResponder(new SpringHttpObjectResponderFactory());
226	
227	        // Add YAML authorize decoration
228	        restArchitect.addRestMethodDecorator(new AuthorizeRestMethodDecorator());
229	
230	        // Add CORS decoration
231	        MomentoKey<CorsConfiguration> corsMomento = restArchitect.addRestMethodDecorator((context) -> {
232	            CorsConfiguration pathCorsConfiguration = loadCorsConfiguration(context.getPath());
233	            CorsConfiguration methodCorsConfiguration = OfficeFloorRestEndpoint.createCorsConfiguration(context.getConfiguration("cors", ComposeCorsConfiguration.class));
234	            context.setMomento(OfficeFloorRestEndpoint.combineCors(pathCorsConfiguration, methodCorsConfiguration));
235	        });
236	
237	        // Add the rest servicing
238	        officeSourceContext.getLogger().info("Loading REST endpoints:");
239	        Map<String, RestEndpoint> restEndpoints = restArchitect.addRestServices(false, "officefloor/rest", propertyList);
240	
241	        // Include the REST endpoints (sorted for deterministic loading and logging)
242	        List<String> endpointPaths = restEndpoints.keySet().stream().sorted((a, b) -> {
243	            int longerSecond = a.length() - b.length(); // short path first
244	            return (longerSecond != 0) ? longerSecond : String.CASE_INSENSITIVE_ORDER.compare(a, b);
245	        }).toList();
246	        for (String endpointPath : endpointPaths) {
247	            RestEndpoint restEndpoint = restEndpoints.get(endpointPath);
248	
249	            // Include the rest endpoint
250	            this.restEndpoints.add(new OfficeFloorRestEndpoint(restEndpoint, corsMomento));
251	
252	            // Log the REST methods (in deterministic order)
253	            List<RestMethod> sortedRestMethods = restEndpoint.getRestMethods().stream()
254	                    .sorted((a, b) -> String.CASE_INSENSITIVE_ORDER.compare(a.getHttpMethod().getName(), b.getHttpMethod().getName()))
255	                    .toList();
256	            for (RestMethod restMethod : sortedRestMethods) {
257	                officeSourceContext.getLogger().info("  " + restMethod.getHttpMethod().getName() + " " + restEndpoint.getPath());
258	            }
259	        }
260	
261	        // Register all the Spring components for use
262	        ConfigurableListableBeanFactory beanFactory = this.applicationContext.getBeanFactory();
263	        officeArchitect.addSupplier("SPRING", new SpringBeanSupplierSource(beanFactory));
264	
265	        // Add access to servlet request/response
266	        this.addOfficeManagedObjectSource(HttpServletRequest.class, new HttpServletRequestManagedObjectSource(), officeArchitect);
267	        this.addOfficeManagedObjectSource(HttpServletResponse.class, new HttpServletResponseManagedObjectSource(), officeArchitect);
268	        webArchitect.enableHttpExternalResponse();
269	
270	        // Allow rendering of views
271	        this.addOfficeManagedObjectSource(ViewResponse.class, new ViewResponseManagedObjectSource(), officeArchitect);
272	
273	        // Obtain the Spring argument checker
274	        SpringMvcArguments.SpringArgumentChecker springArgumentChecker = SpringMvcArguments.getSpringArgumentChecker(officeSourceContext);
275	
276	        // Load in-line configured spring dependencies
277	        officeArchitect.addManagedFunctionAugmentor((context) -> {
278	            ManagedFunctionType<?, ?> functionType = context.getManagedFunctionType();
279	            for (ManagedFunctionObjectType<?> functionParameterType : functionType.getObjectTypes()) {
280	                Class<?> objectType = functionParameterType.getObjectType();
281	
282	                // Obtain the method parameter annotation
283	                MethodParameterAnnotation parameterAnnotation = functionParameterType.getAnnotation(MethodParameterAnnotation.class);
284	                if (parameterAnnotation != null) {
285	
286	                    // Obtain the method details for the parameter
287	                    Method method = parameterAnnotation.getMethod();
288	                    int parameterIndex = parameterAnnotation.getParameterIndex();
289	
290	                    // Determine if in-line configuration of dependency
291	                    if (springArgumentChecker.isSpringArgument(objectType, functionParameterType.getAnnotations())) {
292	                        this.handleSpringArgument(objectType, method, parameterIndex, officeArchitect);
293	                    }
294	                }
295	            }
296	        });
297	
298	        // Configure the Open API
299	        OpenApiArchitect openApiArchitect = OpenApiEmployer.employOpenApiArchitect(officeArchitect, webArchitect, null, officeSourceContext);
300	        openApiArchitect.buildOpenApi(this.openApi, new HashSet<>());
301	
302	        // Configure Office
303	        webArchitect.informOfficeArchitect();
304	    }
305	
306	    private <S> void addOfficeManagedObjectSource(Class<S> objectType, ManagedObjectSource<?, ?> managedObjectSource, OfficeArchitect officeArchitect) {
307	        officeArchitect.addOfficeManagedObjectSource(objectType.getSimpleName(), managedObjectSource)
308	                .addOfficeManagedObject(objectType.getSimpleName(), ManagedObjectScope.THREAD);
309	    }
310	
311	    private void handleSpringArgument(Class<?> objectType, Method method, int parameterIndex, OfficeArchitect officeArchitect) {
312	
313	        // Determine the binding name and qualifier
314	        String bindAndQualifier = SpringTypeQualifierInterrogator.getSpringTypeQualifier(method, parameterIndex);
315	
316	        // Set up the spring argument managed object
317	        this.springArguments.computeIfAbsent(bindAndQualifier, (key) -> {
318	
319	            // Add the argument object
320	            OfficeManagedObject argumentObject = officeArchitect.addOfficeManagedObjectSource(bindAndQualifier, new SpringArgumentManagedObjectSource(objectType, method, parameterIndex))
321	                    .addOfficeManagedObject(bindAndQualifier, ManagedObjectScope.THREAD);
322	
323	            // Add qualifier
324	            argumentObject.addTypeQualification(bindAndQualifier, objectType.getName());
325	
326	            // Return the argument object
327	            return argumentObject;
328	        });
329	    }
330	
331	}
